import json, csv, os, math, sys
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.json"
os.makedirs("/app/submissions", exist_ok=True)

# ---------- load data ----------
def load_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

config = json.load(open(os.path.join(DATA, "config.json")))
products = {r["product_id"]: r for r in load_csv("products.csv")}
vehicles = {r["vehicle_id"]: r for r in load_csv("vehicles.csv")}
compartments = load_csv("compartments.csv")
stations = {r["station_id"]: r for r in load_csv("stations.csv")}
orders = load_csv("orders.csv")
slots = {r["slot_id"]: r for r in load_csv("loading_slots.csv")}
bays = {r["bay_id"]: r for r in load_csv("loading_bays.csv")}
clean_rules = {}
for r in load_csv("terminal_cleaning_rules.csv"):
    clean_rules[(r["from_hose_family"], r["to_hose_family"])] = (float(r["cleanout_min"]), float(r["cleanout_cost"]))
rest_stops = load_csv("rest_stops.csv")
risk_zones = {}
for r in load_csv("risk_zones.csv"):
    risk_zones[(r["from_zone"], r["to_zone"])] = (float(r["time_factor"]), float(r["hazmat_surcharge_factor"]))
road_adj = {}
for r in load_csv("road_adjustments.csv"):
    road_adj[(r["from_node"], r["to_node"])] = (float(r["extra_minutes"]), float(r["extra_km"]))
pair_rules = load_csv("station_product_rules.csv")
exceptions = load_csv("vehicle_station_exceptions.csv")

DEPOT = config["depot_id"]
SHIFT_START = config["shift_start_min"]
SHIFT_END = config["shift_end_min"]
LOAD_DUR = config["loading_duration_min"]
TURNAROUND = config["turnaround_min"]
BASE_SPEED = config["base_speed_kmph"]
SVC_LPM = config["service_liters_per_min"]
BREAK_AFTER = config["driver_break_after_min"]
BREAK_DUR = config["driver_break_duration_min"]
MAX_TRIP_ELAPSED = config["max_trip_elapsed_min"]
LATE_PEN = config["late_penalty_per_min"]
HAZ_PER_KM = config["hazmat_surcharge_per_km"]
TOL = config["feasibility_tolerance"]

# ---------- coordinates ----------
coords = {}
coords[DEPOT] = (config["terminal_lat"], config["terminal_lon"])
for s, r in stations.items():
    coords[s] = (float(r["lat"]), float(r["lon"]))
for r in rest_stops:
    coords[r["node_id"]] = (float(r["lat"]), float(r["lon"]))

def haversine_km(a, b):
    lat1, lon1 = coords[a]; lat2, lon2 = coords[b]
    R = 6371.0
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = math.radians(lat2 - lat1); dl = math.radians(lon2 - lon1)
    h = math.sin(dp/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(h))

# ---------- travel ----------
def travel_time(i, j):
    d = haversine_km(i, j)
    zi = stations[i]["risk_zone"] if i in stations else ("suburban" if i.startswith("REST") else "industrial")
    zj = stations[j]["risk_zone"] if j in stations else ("suburban" if j.startswith("REST") else "industrial")
    if i == DEPOT: zi = "industrial"
    if j == DEPOT: zj = "industrial"
    tf, hf = risk_zones.get((zi, zj), (1.0, 1.0))
    t = d / BASE_SPEED * 60.0 * tf
    em, ek = road_adj.get((i, j), (0.0, 0.0))
    t += em
    return t, d + ek, hf

# ---------- tasks (station-level merged orders) ----------
station_orders = {}
for o in orders:
    station_orders.setdefault(o["station_id"], []).append(o)

tasks = []
for s, olist in station_orders.items():
    task = {
        "station": s,
        "orders": olist,
        "demand": sum(float(o["demand_liters"]) for o in olist),
        "min": sum(float(o["min_liters"]) for o in olist),
        "families": sorted(set(products[o["product_id"]]["hose_family"] for o in olist)),
        "products": sorted(set(o["product_id"] for o in olist)),
        "weight": sum(float(o["demand_liters"]) * float(products[o["product_id"]]["density_kg_per_liter"]) for o in olist),
    }
    tasks.append(task)
task_by_station = {t["station"]: t for t in tasks}

# ---------- compartments per vehicle ----------
veh_comps = {}
for r in compartments:
    v = r["vehicle_id"]
    veh_comps.setdefault(v, []).append({
        "id": r["compartment_id"],
        "group": r["group"],
        "cap": float(r["capacity_liters"]),
        "prods": set(r["compatible_products"].split("|")),
    })

# ---------- eligibility ----------
def station_allowed(v, s):
    st = stations[s]
    allowed = st["access_class"] in vehicles[v]["allowed_station_classes"].split("|")
    for e in exceptions:
        if e["vehicle_id"] == v and e["station_id"] == s:
            if e["rule"] == "blocked":
                return False
            elif e["rule"] == "allowed":
                return True
    return allowed

def task_fits_vehicle(v, task):
    if not station_allowed(v, task["station"]):
        return False
    veh = vehicles[v]
    if task["demand"] > float(veh["max_volume_liters"]):
        return False
    if task["weight"] > float(veh["max_payload_kg"]):
        return False
    # compartment fit: each order needs distinct compatible compartment with cap >= order demand
    comps = veh_comps[v]
    orders_list = task["orders"]
    # greedy check via simple matching
    def can_assign(ol, comps):
        if not ol:
            return True
        o = ol[0]
        for ci, c in enumerate(comps):
            if o["product_id"] in c["prods"] and float(o["demand_liters"]) <= c["cap"]:
                if can_assign(ol[1:], comps[:ci] + comps[ci+1:]):
                    return True
        return False
    return can_assign(orders_list, comps)

def bay_ok(b, v, task):
    bay = bays[b]
    if bay["max_vehicle_class"] not in ("S", "M", "H"):
        pass
    # vehicle class limit: bay max class must be >= vehicle class
    cls_order = {"S": 0, "M": 1, "H": 2}
    if cls_order[vehicles[v]["vehicle_class"]] > cls_order[bay["max_vehicle_class"]]:
        return False
    fams = set(bay["compatible_hose_families"].split("|"))
    return set(task["families"]).issubset(fams)

# ---------- enumerate feasible (v, t, b, s) ----------
feas = []  # list of dicts
for v in vehicles:
    for t in slots:
        for b in bays:
            for task in tasks:
                s = task["station"]
                if not task_fits_vehicle(v, task):
                    continue
                if not bay_ok(b, v, task):
                    continue
                st = stations[s]
                load_start = float(t["start_min"])
                load_end = load_start + LOAD_DUR
                tt, dist, hf = travel_time(DEPOT, s)
                arrival = load_end + tt
                if arrival < float(st["earliest_min"]) - TOL or arrival > float(st["latest_min"]) + TOL:
                    continue
                # service time
                svc = float(st["fixed_service_min"]) + task["demand"] / SVC_LPM
                departure = arrival + svc
                return_t, _, _ = travel_time(s, DEPOT)
                trip_end = departure + return_t
                if trip_end > SHIFT_END + TOL:
                    continue
                elapsed = trip_end - load_start
                if elapsed > MAX_TRIP_ELAPSED + TOL:
                    continue
                # work limit: total on-duty from shift start
                if trip_end - SHIFT_START > float(vehicles[v]["work_limit_min"]) + TOL:
                    continue
                # driver break: if on-duty between depot departure and return exceeds threshold
                on_duty = (departure - load_start) + return_t
                # single stop, no rest needed if on_duty <= BREAK_AFTER; else infeasible for single-stop
                if on_duty > BREAK_AFTER + TOL:
                    # would need rest stop; allow only if we can insert one (skip for simplicity: mark infeasible)
                    continue
                late = max(0.0, arrival - float(st["preferred_latest_min"]))
                travel_cost = float(vehicles[v]["cost_per_km"]) * dist * 2 + dist * 2 * hf * HAZ_PER_KM
                slot_cost = float(t["slot_cost"])
                bay_cost = float(b["bay_cost"])
                fixed = float(vehicles[v]["fixed_trip_cost"])
                feas.append({
                    "v": v, "t": t, "b": b, "s": s,
                    "arrival": arrival, "departure": departure, "trip_end": trip_end,
                    "late": late, "travel_cost": travel_cost,
                    "cost": fixed + slot_cost + bay_cost + travel_cost + late * LATE_PEN,
                    "dist": dist, "hf": hf,
                })

print(f"Feasible assignments: {len(feas)}")

# ---------- build MIP ----------
model = Model("fuel_tanker")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# index feasible combos
combo_idx = {i: f for i, f in enumerate(feas)}
y = {}
for i, f in enumerate(feas):
    y[i] = model.addVar(name=f"y_{i}", vtype="B", lb=0, ub=1, obj=f["cost"])

# coverage: each task (station) exactly once
for task in tasks:
    s = task["station"]
    idxs = [i for i, f in enumerate(feas) if f["s"] == s]
    if not idxs:
        print(f"WARNING: no feasible assignment for station {s}")
        continue
    model.addCons(quicksum(y[i] for i in idxs) == 1, name=f"cov_{s}")

# rack capacity per slot
for t in slots:
    cap = int(t["rack_capacity"])
    idxs = [i for i, f in enumerate(feas) if f["t"] == t]
    model.addCons(quicksum(y[i] for i in idxs) <= cap, name=f"rack_{t}")

# bay single use per slot
for t in slots:
    for b in bays:
        idxs = [i for i, f in enumerate(feas) if f["t"] == t and f["b"] == b]
        if idxs:
            model.addCons(quicksum(y[i] for i in idxs) <= 1, name=f"bay_{t}_{b}")

# vehicle max trips
for v in vehicles:
    maxtr = int(vehicles[v]["max_trips"])
    idxs = [i for i, f in enumerate(feas) if f["v"] == v]
    model.addCons(quicksum(y[i] for i in idxs) <= maxtr, name=f"veh_{v}")

# delivery quantities
q = {}
for o in orders:
    oid = o["order_id"]
    q[oid] = model.addVar(name=f"q_{oid}", vtype="C", lb=float(o["min_liters"]), ub=float(o["demand_liters"]), obj=0.0)

# short-fill penalty in objective
short_pen = {}
for o in orders:
    oid = o["order_id"]
    pen = float(o["shortfall_penalty_per_liter"])
    short_pen[oid] = pen
    # penalty = pen * (demand - q)
    model.chgVarObj(q[oid], -pen * float(o["demand_liters"]))
    # add constant pen*demand to objective via a fixed variable trick: use setObjective with expression
# We'll build objective explicitly instead. Reset objective.
obj_terms = []
for i, f in enumerate(feas):
    obj_terms.append(f["cost"] * y[i])
for o in orders:
    oid = o["order_id"]
    obj_terms.append(short_pen[oid] * (float(o["demand_liters"]) - q[oid]))
model.setObjective(quicksum(obj_terms), sense="minimize")

# compartment assignment: for each feasible combo, assign each order to a compartment
# w[i, oid, k] binary
w = {}
comp_ids_by_veh = {}
for v in vehicles:
    comp_ids_by_veh[v] = [c["id"] for c in veh_comps[v]]

for i, f in enumerate(feas):
    v = f["v"]
    s = f["s"]
    task = task_by_station[s]
    for o in task["orders"]:
        oid = o["order_id"]
        for c in veh_comps[v]:
            if o["product_id"] not in c["prods"]:
                continue
            if float(o["demand_liters"]) > c["cap"]:
                continue
            w[(i, oid, c["id"])] = model.addVar(name=f"w_{i}_{oid}_{c['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# each order assigned to exactly one compartment when its combo is chosen
for i, f in enumerate(feas):
    v = f["v"]
    s = f["s"]
    task = task_by_station[s]
    for o in task["orders"]:
        oid = o["order_id"]
        opts = [c["id"] for c in veh_comps[v] if o["product_id"] in c["prods"] and float(o["demand_liters"]) <= c["cap"]]
        if not opts:
            continue
        model.addCons(quicksum(w[(i, oid, k)] for k in opts) == y[i], name=f"wassign_{i}_{oid}")

# each compartment used at most once per combo
for i, f in enumerate(feas):
    v = f["v"]
    for c in veh_comps[v]:
        cid = c["id"]
        task = task_by_station[f["s"]]
        opts = [o["order_id"] for o in task["orders"] if o["product_id"] in c["prods"] and float(o["demand_liters"]) <= c["cap"]]
        if opts:
            model.addCons(quicksum(w[(i, oid, cid)] for oid in opts) <= 1, name=f"wcomp_{i}_{cid}")

# quantity = demand if delivered (link q to y)
for i, f in enumerate(feas):
    s = f["s"]
    task = task_by_station[s]
    for o in task["orders"]:
        oid = o["order_id"]
        d = float(o["demand_liters"])
        m = float(o["min_liters"])
        # q[oid] >= m * y_sum ... but y is per combo; the covering combo determines q
        # Since exactly one combo covers s, q[oid] is the delivery for that order.
        # Link: q[oid] <= d * (sum of y covering s) = d (always, since covered)
        # q[oid] >= m (already lb)
        pass

# ---------- solve ----------
model.optimize()
status = model.getStatus()
print(f"Status: {status}")
nsols = model.getNSols()
print(f"Solutions: {nsols}")
best = model.getBestSol()
objval = model.getObjVal()
print(f"Objective: {objval}")

# ---------- extract solution ----------
trips_out = []
if best is not None:
    used_combos = []
    for i, f in enumerate(feas):
        val = model.getVal(y[i])
        if val > 0.5:
            used_combos.append((i, f))
    # group by (v, t, b)
    groups = {}
    for i, f in used_combos:
        key = (f["v"], f["t"], f["b"])
        groups.setdefault(key, []).append((i, f))
    for (v, t, b), items in groups.items():
        trip_id = f"{v}_{len([x for x in trips_out if x['vehicle_id']==v])+1}"
        stops = []
        deliveries = []
        for i, f in sorted(items, key=lambda x: x[1]["arrival"]):
            s = f["s"]
            seq = len(stops) + 1
            stops.append({"node_id": s, "arrival_min": round(f["arrival"], 8), "departure_min": round(f["departure"], 8)})
            task = task_by_station[s]
            for o in task["orders"]:
                oid = o["order_id"]
                qv = model.getVal(q[oid])
                # find compartment
                comp_id = None
                for c in veh_comps[v]:
                    if (i, oid, c["id"]) in w:
                        if model.getVal(w[(i, oid, c["id"])]) > 0.5:
                            comp_id = c["id"]
                            break
                if comp_id is None:
                    # fallback: pick any compatible
                    for c in veh_comps[v]:
                        if o["product_id"] in c["prods"] and float(o["demand_liters"]) <= c["cap"]:
                            comp_id = c["id"]
                            break
                deliveries.append({
                    "order_id": oid,
                    "stop_sequence": seq,
                    "compartment_id": comp_id,
                    "quantity_liters": round(qv, 8),
                })
        trips_out.append({
            "vehicle_id": v,
            "trip_id": trip_id,
            "bay_id": b,
            "load_start_min": float(t["start_min"]),
            "stops": stops,
            "deliveries": deliveries,
        })

solution = {"trips": trips_out}
with open(OUT, "w") as f:
    json.dump(solution, f, indent=2)
print(f"Wrote {OUT} with {len(trips_out)} trips")

# ---------- validation ----------
covered = set()
for trip in trips_out:
    for d in trip["deliveries"]:
        covered.add(d["order_id"])
all_orders = set(o["order_id"] for o in orders)
missing = all_orders - covered
print(f"Orders covered: {len(covered)}/{len(all_orders)}, missing: {missing}")

# write solve log
log = f"""# Solve Log — fuel_tanker_compartment_routing

## Approach
- Set-partitioning MIP: each station task covered exactly once by a (vehicle, slot, bay) combo.
- Preprocessing: travel times with risk-zone factors and road adjustments; eligibility filters (access, volume, payload, compartments, bay families/class, windows, work limits, driver break).
- Objective: fixed trip cost + slot cost + bay cost + travel cost + hazmat surcharge + lateness + short-fill penalty.
- SCIP gaprel 0.0005, time limit {time_limit}s.

## Solver status
- Status: {status}
- Solutions: {nsols}
- Objective: {objval}

## Validation
- Orders covered: {len(covered)}/{len(all_orders)}
- Missing: {missing if missing else 'none'}
- Trips: {len(trips_out)}
"""
with open("/app/submissions/solve_log.md", "w") as f:
    f.write(log)
print("Done.")
